INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','386fe3cf-136c-474e-92a7-2b765b01ae3e',NULL,1947,8,7,'Society & Human Rights',65,'{"id":"386fe3cf-136c-474e-92a7-2b765b01ae3e","ad_day":7,"ad_date":null,"ad_year":1947,"bs_date":null,"country":"United States","sources":[],"ad_month":8,"category":"Society & Human Rights","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"Thor Heyerdahl ''s balsa wood raft, the Kon-Tiki, smashes into the reef at Raroia in the Tuamotu Islands after a 101-day, 7,000 kilometres (4,300 mi) journey across the Pacific Ocean in an attempt to prove that pre-historic peoples could have traveled from South America.","title_ne":"थोर हेयरडाहलको बाल्सा काठको राफ्ट, कोन-टिकी, प्रशान्त महासागर पार गर्दै १०१ दिनको ७,००० किलोमिटर (४,३०० माइल) यात्रा गरेपछि तुआमोटु टापुहरूको रारोइयाको चट्टानमा ठोक्किन्छ, जसले प्रागैतिहासिक मानिसहरू दक्षिण अमेरिकाबाट यात्रा गर्न सक्थे भन्ने प्रमाणित गर्ने प्रयास गर्दछ।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:35.161956+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/Thor_Heyerdahl","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:35.161956+00:00","source_name":"User-provided historical dataset","country_code":"US","image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=Thor%20Heyerdahl&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"Thor Heyerdahl","source_record_id":"0807-1947-e-fjrwuq","verification_status":"source-backed","event_date_precision":"day"}','2026-09-19T03:30:35.161956+00:00');
